import type { Page } from '@playwright/test'
import { devices, expect, test } from '@playwright/test'
import { bootSdk } from './helpers/boot'

// The get-app screen's QR code is bundled (src/assets/get-app-qr-code.svg,
// generated by scripts/make-get-app-qr.py), not fetched from the assets
// bucket: the bucket copy pointed at a paid short-link service we no longer
// use.

// A signed-out shopper reaches the get-app screen from the landing screen's
// "Create your Mini Me". (Signed-in shoppers without an avatar reach the same
// content from the pill on the try-on overlays: demo-avatar.spec.ts.)
async function openGetApp(page: Page) {
  await bootSdk(page, { loggedIn: false })
  await page.getByRole('button', { name: /quick view/i }).click()
  await page.getByRole('dialog').getByRole('button', { name: 'Create your Mini Me' }).click()
}

test('get-app: the QR code is the bundled one, for the download page', async ({ page }) => {
  await openGetApp(page)

  const qr = page.getByRole('img', { name: 'QR Code' })
  await expect(qr).toBeVisible()
  const { src, loaded } = await qr.evaluate((img: HTMLImageElement) => ({
    src: img.getAttribute('src') ?? '',
    loaded: img.complete && img.naturalWidth > 0,
  }))
  expect(loaded).toBe(true)
  // Inlined into the bundle, so no request to the bucket.
  expect(src.startsWith('data:image/svg+xml')).toBe(true)
  expect(src).not.toContain('get-app-qr-code.png')
  // The generator stamps the encoded URL into the SVG.
  expect(decodeURIComponent(src)).toContain('QR code for https://www.thefittingroom.tech/download.')
})

test.describe('mobile', () => {
  const { defaultBrowserType: _browser, ...pixel5 } = devices['Pixel 5']
  test.use(pixel5)

  test('get-app: the store badges open the current app listings', async ({ page }) => {
    await page.addInitScript(() => {
      const opened: string[] = []
      ;(window as unknown as { __opened: string[] }).__opened = opened
      window.open = (url?: string | URL) => {
        opened.push(String(url))
        return null
      }
    })
    await openGetApp(page)

    // On a phone the screen offers the stores instead of the QR code.
    await expect(page.getByRole('img', { name: 'QR Code' })).toHaveCount(0)
    await page.getByRole('img', { name: 'Apple Store' }).click()
    await page.getByRole('img', { name: 'Google Play' }).click()
    const opened = await page.evaluate(() => (window as unknown as { __opened: string[] }).__opened)
    expect(opened).toEqual([
      'https://apps.apple.com/app/id1577417373',
      'https://play.google.com/store/apps/details?id=com.thefittingroom.app',
    ])
  })
})
